package com.greenocean.backend.professional.service;
import com.greenocean.backend.catalog.service.GrowthLibrary;import com.greenocean.backend.common.exception.*;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.security.*;import java.util.HexFormat;
@Service @Transactional
public class CredentialDocuments {
 private final JdbcTemplate db;private final ProfessionalDocumentStorage storage;private final CredentialScanner scanner;private final ProfessionalAuthority authority;private final GrowthLibrary staff;
 public CredentialDocuments(JdbcTemplate db,ProfessionalDocumentStorage storage,CredentialScanner scanner,ProfessionalAuthority authority,GrowthLibrary staff){this.db=db;this.storage=storage;this.scanner=scanner;this.authority=authority;this.staff=staff;}
 public Map<String,Object> detail(UUID actor,UUID id){staff.staff(actor);var rows=db.queryForList("SELECT * FROM professional_verifications WHERE id=?",id);if(rows.isEmpty())throw new NotFoundException("Application was not found");var r=rows.getFirst();r.put("documents",db.queryForList("SELECT id,original_name,content_type,byte_size,scan_status,scanned_at,encryption_version FROM professional_application_documents WHERE application_id=? ORDER BY uploaded_at,id",id));return (Map<String,Object>)ProfessionalAuthority.jsonSafe(r);}
 public Map<String,Object> scan(UUID actor,UUID id,String reason){staff.staff(actor);ProfessionalAuthority.text(reason,1000);var owners=db.queryForList("SELECT v.id AS application_id,v.professional_user_id FROM professional_application_documents d JOIN professional_verifications v ON v.id=d.application_id WHERE d.id=?",id);if(owners.isEmpty())throw new NotFoundException("Credential document was not found");UUID owner=(UUID)owners.getFirst().get("professional_user_id");db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",owner);authority.lock(owner);db.queryForList("SELECT id FROM professional_verifications WHERE id=? FOR UPDATE",owners.getFirst().get("application_id"));var rows=db.queryForList("SELECT * FROM professional_application_documents WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new NotFoundException("Credential document was not found");var d=rows.getFirst();if(((Number)d.get("encryption_version")).intValue()!=1)throw new ConflictException("Legacy unencrypted documents require controlled re-upload or migration");byte[] plain=storage.read((String)d.get("storage_key"),(UUID)d.get("application_id"));try{if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(plain)).equals(d.get("sha256")))throw new ConflictException("Credential integrity check failed");}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}var result=scanner.scan(plain);db.update("UPDATE professional_application_documents SET scan_status=?,scanner_reference=?,scanned_at=CASE WHEN ?='PENDING' THEN NULL ELSE CURRENT_TIMESTAMP END,reviewed_by=? WHERE id=?",result.state(),result.reference(),result.state(),actor,id);db.update("UPDATE professional_verifications SET qualification_revision=qualification_revision+1 WHERE id=?",d.get("application_id"));authority.audit(actor,"CREDENTIAL_SCAN_"+result.state(),id,reason);return Map.of("state",result.state(),"available",!result.state().equals("PENDING"));}
 public byte[] read(UUID actor,UUID id,String purpose){authority.actor(actor);ProfessionalAuthority.text(purpose,1000);var rows=db.queryForList("SELECT d.*,v.professional_user_id FROM professional_application_documents d JOIN professional_verifications v ON v.id=d.application_id WHERE d.id=?",id);if(rows.isEmpty())throw new NotFoundException("Credential document was not found");var d=rows.getFirst();if(!actor.equals(d.get("professional_user_id")))staff.staff(actor);if(!"CLEAN".equals(d.get("scan_status"))||((Number)d.get("encryption_version")).intValue()!=1||d.get("scanner_reference")==null)throw new ForbiddenException("Quarantined documents are not available for viewing");authority.audit(actor,"CREDENTIAL_DOCUMENT_READ",id,purpose);return storage.read((String)d.get("storage_key"),(UUID)d.get("application_id"));}
 public record Download(byte[] bytes,String mime,String filename){}
 public Download download(UUID actor,UUID id,String purpose){byte[] bytes=read(actor,id,purpose);String mime=db.queryForObject("SELECT content_type FROM professional_application_documents WHERE id=?",String.class,id);String extension=switch(mime){case "application/pdf"->"pdf";case "image/png"->"png";case "image/jpeg"->"jpg";default->throw new ForbiddenException("Unsupported credential format");};return new Download(bytes,mime,"credential."+extension);}
}
